  const getChannelMasterVolume = (
    mixerState: BroadcastSettings,
    channelId: MixerTakeChannelKey,
  ): number => {
    switch (channelId) {
      case "song":
        return mixerState.songMasterVolume;
      case "stream":
        return mixerState.streamMasterVolume;
      case "instants":
        return mixerState.instantMasterVolume;
      case "sceneInstant":
