    }

    if (!selectedScene) {
      sceneEditorAutosaveSignatureRef.current = "";
      sceneEditorDirtyRef.current = false;
      sceneEditorRevisionRef.current = 0;
      setSceneAttributeSaveError(null);
      sceneEditorPropsRef.current = {};
      setSceneEditorProps({});
