  const sceneAttributeSaveDrainPromiseRef = useRef<Promise<void> | null>(null);
  const sceneAttributeRetryTimerRef = useRef<number | null>(null);
  const sceneAttributeFlushKickTimerRef = useRef<number | null>(null);
