import type {
  BroadcastSettings,
  MixerChannelSetting,
  ProgramAudioMeterLevels,
  ProgramSongPlaybackState,
  SceneInstantPlaybackState,
  ProgramState,
  Scene,
  ProgramUpdateTopic,
  MixerTakeChannelKey,
  MixerTakePresetSide,
  MixerTakeApplyingMap,
  MixerTakeTimerMap,
  MixerTakeRunIdMap,
  MixerTakePresetDbMap,
  ComponentPropsMap
} from '../models/broadcast';
import { dbToFader, faderToDb, faderToGain } from './audioTaper';

